	public static void main(String[] args) {
		Main main = new Main();
		main.solve();
		System.exit(0);
	}

	void solve() {
		int N = nextInt();
		int [] B = nextIntArray(N-1);
		int [] unknownA = new int [N];

		unknownA[0] = B[0];
		unknownA[N-1] = B[N-2];
		for(int i=1;i<N-1;i++) {
			unknownA[i] = Math.min(B[i-1],B[i]);
		}
		long res = 0;
		for(int i : unknownA) {
			res += i;
		}

		out.println(res);
	}

