        int array[] = new int[n];

        for(int i=0; i<n; i++) {
            array[i] = sc.nextInt();
            System.out.print(array[i]);
            if(i<array.length-1) {
                System.out.print(" ");
            }
        }

        System.out.println();

        sc.close();

        for(int i=1; i<array.length; i++) {

            int key = array[i];
            /* insert A[i] into the sorted sequence A[0,...,j-1] */
            int j = i-1;
            while(j>=0 && array[j]>key) {
                array[j+1] = array[j];
                j--;
            }
            array[j+1] = key;

            for(int num=0; num<array.length; num++) {
                System.out.print(array[num]);
                if(num != array.length-1) {
                    System.out.print(" ");
                } else {
                    System.err.println();
                }
            }
        }

    }
}

