		}
		long ans = 1;
		long w = 1000000007;
		for (int i = 0; i < m; i++) {
			if (a[i] - now > 2) {
				dp = new long[a[i] - now];
				dp[0] = 0;
				dp[1] = 1;
				dp[2] = 2;
				for (int j = 3; j < a[i] - now; j++) {
					dp[j] = dp[j - 1] + dp[j - 2];
				}
				dp[ a[i] - now - 1] = dp[a[i] - now - 1] % w;
				ans = (long) (ans * dp[a[i] - now - 1]) % w;
				now = a[i] + 1;
			} else if (a[i] - now > 0) {
				ans = (long) (ans * (a[i] - now)) % w;
				now = a[i] + 1;
			} else {
				ans = 0;
				break;
			}
		}
		if (n - now + 1 > 2) {
			dp = new long[n - now + 1];
			dp[0] = 0;
			dp[1] = 1;
			dp[2] = 2;
			for (int j = 3; j < n - now + 1; j++) {
				dp[j] = dp[j - 1] + dp[j - 2];
			}
			 dp[n -now] = dp[n - now]% w;
			ans = (long) (ans * dp[n - now]) % w;
		} else if (n - now + 1 > 0) {
