int isprime(int x){
  if(x == 2) return 1;
  if(x < 2 || x%2==0) return -1; 
  int i = 3;
  while(i <= sqrt(x)){
    if (x % i ==0) return -1;
    i = i+2;
  }
  return 1;
}

