				if(height[i]!=0) height[i]--;
			}
		}
		System.out.println(count);
	}

	static boolean all_zero(int n, int[] array) {
		for(int i=0;i<n;i++) {
			if(array[i]!=0) return false;
		}
		return true;
	}
}

