      int max=Integer.MIN_VALUE;
      for(int i=1;i<n;i++){
          max=Math.max(max,Math.abs(a[i]-a[i-1]));
      }
      if(a[0]==0)
          a[0]=k;
      System.out.println(k-Math.max(max,Math.abs(a[n-1]-a[0])));

    }
}

