import java.util.Scanner;

public class Main{
    public static void main(String[] args) {
        final int T = 0;
        final int X = 1;
        final int Y = 2;
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        int[][] travel = new int[n][3];
        for(int i=0;i<n;i++){
            for(int j=0;j<3;j++){
                travel[i][j] = Integer.parseInt(sc.next());
            }
        }
        boolean can = true;
        int pt=0, px=0, py=0;
        for(int i=0;i<n;i++){
            int d = length(px, py, travel[i][X], travel[i][Y]);
            int t = travel[i][T] - pt;
            if(d>t){
                can = false;
                break;
            }else if((t-d)%2==1){
                can = false;
                break;
            }
            px = travel[i][X]; py=travel[i][Y]; pt=travel[i][T];
        }
        if(can){
            System.out.println("Yes");
        }else{
            System.out.println("No");
        }
    }
    static int length(int px, int py, int cx, int cy){
        return(Math.abs(cx-px)+Math.abs(cy-py));
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        PrintWriter out = new PrintWriter(System.out);
        InputStreamScanner in = new InputStreamScanner(System.in);
        new Main().solve(in, out);
        out.flush();
    }

    private void solve(InputStreamScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        int[] c = new int[n];
        for (int i = 0; i < m * 2; i++) {
            c[in.nextInt() - 1]++;
        }

        for (int i = 0; i < n; i++) {
            out.println(c[i]);
        }

    }

    static class InputStreamScanner {

        private InputStream in;

        private byte[] buf = new byte[1024];
        private int len = 0;
        private int off = 0;

        InputStreamScanner(InputStream in)	{
            this.in = in;
        }

        String next() {
            StringBuilder sb = new StringBuilder();
            for (int b = skip(); !isSpace(b);){
                sb.appendCodePoint(b);
                b = read();
            }
            return sb.toString();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        char nextChar() {
            return (char)skip();
        }

        int skip() {
            for (int b; (b = read()) != -1;) {
                if (!isSpace(b)) {
                    return b;
                }
            }
            return -1;
        }

        private boolean isSpace(int c) {
            return c < 33 || c > 126;
        }

        private int read() {
            if (len == -1) {
                throw new InputMismatchException("End of Input");
            }
            if (off >= len){
                off = 0;
                try {
                    len = in.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException(e.getMessage());
                }
                if (len <= 0) {
                    return -1;
                }
            }
            return buf[off++];
        }
    }
}

