class Main {

    static PrintWriter out;
    static InputReader sc;

    public static void main(String[] args) {
        sc = new InputReader(System.in);
        out = new PrintWriter(System.out);
        solve();
        out.flush();
    }

    static void solve() {
        int N = sc.nextInt();
        int[] A = sc.nextIntArray(N + 1);
        int[] B = sc.nextIntArray(N);
        int ans = 0;
        if (A[0] < B[0]) {
            ans += A[0];
            B[0] -= A[0];
        } else {
            ans += B[0];
            B[0] = 0;
        }
        for (int i = 1; i < N; i++) {
            if (A[i] < B[i - 1]) {
                ans += A[i];
                A[i] = 0;
            } else {
                ans += B[i - 1];
                A[i] -= B[i - 1];
            }
            if (A[i] < B[i]) {
                ans += A[i];
                B[i] -= A[i];
            } else {
                ans += B[i];
                B[i] = 0;
            }
        }
        if (A[N] < B[N - 1]) {
            ans += A[N];
        } else {
            ans += B[N - 1];
        }
        out.println(ans);
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg == null) {
                j.add("null");
            } else if (arg instanceof int[]) {
