public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        long n = sc.nextLong();
        long k = sc.nextLong();
        sc.close();

        if (k > n || k == 0) {
            System.out.print(n);
            return;
        }

        long count = n / k;//n > k
        long biggerK = k * (count + 1);
        long smallerK = k * (count);
        long ans = Math.min(Math.min(k, Math.abs(n - biggerK)), Math.abs(n - smallerK));
        System.out.print(ans);
    }
}

