		double divM = (double) 1 / (4 * M);
		boolean judge = true;
		int voteSum = 0;
		Integer[] arrayA = new Integer[N];

		for (int i = 0; i < N; i++) {
			arrayA[i] = Integer.parseInt(sc.next());
			voteSum += arrayA[i];
		}
