		//降順にソートする
		Arrays.sort(arrayA, Comparator.reverseOrder());

		for (int i = 0; i < M; i++) {
			//総投票数の1/4M未満であるか
			if ((double) arrayA[i] / voteSum < divM) {
				judge = false;
				break;
			}
		}
		System.out.println(judge ? "Yes" : "No");
	}
}

