		M = in.nextInt();
		int[] s = new int[N+2];
		for(int i=0; i<M; ++i){
			//[L,R] -> [L, R+1)
			int L = in.nextInt();
			int R = in.nextInt();
			s[L]++;
			s[R+1]--;
		}
