        String T = scanner.nextLine();
        int min = Integer.MAX_VALUE;
        for(int i = 0; i<S.length()-T.length(); i++){
            min = Math.min(min, find(S.substring(i, i+T.length()), T));
        }
        System.out.println(min);
    }

