        PrintWriter out = new PrintWriter(outputStream);
        Task solver = new Task();
        solver.solve(1, in, out);
        out.close();
    }

    static class Task {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            long res = 0;
            HashMap<String, Integer> hm = new HashMap<String, Integer>();
            for (int i = 0; i < n; i++) {
                String s = in.next();
