		Scanner keyboard = new Scanner(System.in); 

		int W  = keyboard.nextInt();
		int H  = keyboard.nextInt();
		int x  = keyboard.nextInt();
		int y  = keyboard.nextInt();

		double men = (W*H)/2.0;
		double a = x*H;
		double b = (W*H)-a;
		double c = y*W;
		double d = (W*H)-c;

		double xx = Math.min(a, b);
		double yy = Math.min(c, d);

		int hou = 0;

		if(xx == men) {
			hou ++;
		}
		if(yy == men) {
			hou ++;
		}

		if(hou <= 1) {
			hou = 0;
		}else {
			hou = 1;
		}

		System.out.print(men + " " + hou);
		keyboard.close();	
	}
}

