import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int N = sc.nextInt();
		int[] numMonsters = new int[N+1];
		int[] capasityHero = new int[N];		
		for(int i=0;i<N+1;i++) {
			numMonsters[i] = sc.nextInt();
		}		
		for(int i=0;i<N; i++) {
			capasityHero[i] = sc.nextInt();
		}

		int sum = 0;
		int extra = 0;
		for(int i=0;i<N;i++) {
			sum += Math.min(numMonsters[i] , capasityHero[i]);
			extra = Math.max(0, capasityHero[i] - numMonsters[i]);
			sum += Math.min(extra, numMonsters[i+1]);
			numMonsters[i+1] = Math.max(numMonsters[i+1] - extra,0);
		}

		System.out.println(sum);

		sc.close();	
	}

}

