		int n = sc.nextInt();
		int k = sc.nextInt();
		double ans = 0;

		for(int i = 1;i <= n;i++){
			double sub = ((double)1/n);

			int two = 0;
			int sum = i;
			while(sum < k){
				two++;				//1,2,3,4
				sum *= 2;			//2,4,8,16
			}
			sub *= (double)(1/Math.pow(2, two));
		//	System.out.println("sub " + sub);

			ans += sub;
		}
		System.out.print(ans);

	}


	static int gcd(int a,int b){				//最大公約数を返す
		if(b == 0){
			return a;
		}else{
			return gcd(b, a%b);
		}
	}





static String deletestr(String base,String remove){
	boolean flag = true;
	for(int i = 0;i < remove.length();i++){
		if(i == base.length()){
			flag = false;
			break;
		}
		if(base.charAt(i) - remove.charAt(i) != 0 && base.charAt(i) - remove.charAt(i) != 32 &&remove.charAt(i) - base.charAt(i)  != 32){
			flag = false;
			break;
		}
	}

	if(flag){
		base = base.substring(remove.length());
	}

	return base;

}



}


