				if(acms[i - 1] >  acmsd[i - 1]) {
					x = acms[i - 1];
					y = acmsd[i - 1];
				} else {
					y = acms[i - 1];
					x = acmsd[i - 1];
				}
				int val = 	calc( x, y ) ;
				if(val > max) {
					max = val;
				}
			}
		}

		System.out.println(max);
	}
}

