            sb.append((char)(v+'a'));
            t=(t/26);
        }
        char[] d = sb.toString().toCharArray();
        int i = 0;
        int j = d.length-1;
        while(i<j){
            char tt = d[i];
            d[i] = d[j];
            d[j] = tt;
            i++;
            j--;
        }
        writer.println(new String(d));
    }

    public static void main(String[] args) throws IOException {
