        double angle = hour-min;
        if (angle > 180) {
        	angle -= 180;
        }

        double ans = a*a + b*b - 2*a*b * Math.cos(angle / 180 * Math.PI);
        System.out.println(String.format("%.20f", Math.sqrt(ans)));
    }
}

