    static class CRemainderMinimization2019 {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            long l = in.nextLong();
            long r = in.nextLong();
            long ans = Integer.MAX_VALUE;
            long s = l % 2019;
            long t = r % 2019;
            if (t <= s) {
                out.println(0);
                return;
            }
            if ((r - l) / 2019 >= 1) {
                out.println(0);
                return;
            }
            for (long i = s; i <= t; i++) {
                for (long j = i + 1; j <= t; j++) {
                    ans = Math.min(ans, (i * j) % 2019);
                }
            }
            out.println(ans);


        }

    }

