    static  long factorial (int n){
       long fact = 1;
       for (int i = 2; i<=n; i++){
           fact*= i;
       }
       return  fact;
    }
    static long  combinationOfTwo(int n){
        return factorial(n)/(factorial(n-2)*factorial(2));

    }
