		n = scanner.nextInt();
		k = scanner.nextInt(); // 買う果物

		while (n-- > 0){
			pq.add(scanner.nextInt());
		}

		int sum = 0;
		while (k-- > 0){
			sum += pq.poll();
		}
		System.out.println(sum);

	}

}

