			System.out.print(" " + a[k]);
		}
		System.out.println();
		for (int i = 1; i < n; i++) {
			int v = a[i];
			int j = i - 1;
			while (j >= 0 && a[j] > v) {
				a[j+1] = a[j];
				j--;
			}
			a[j+1] = v;
			System.out.print(a[0]);
			for (int k = 1; k < n; k++) {
				System.out.print(" " + a[k]);
			}
			System.out.println();
		}
	}
