        for (int i = 0; i < T.length; i++){
            T[i] = sc.nextInt();
        }
        return true;
    }

    static int solve(){
        int res = 0;
        for (int key : T){
            if( binarySearch(S, key) ) res++;
        }
        return res;
    }
    /**
