     * @param targets := ??¢?´¢??????????±???¨????????????
     * @param key := ??¢?????????????´?
     * @return res
     */
    static boolean binarySearch(int[] targets, int key){
        int left = 0, right = targets.length;
        while ( left < right ){
            int middle = (left+right)/2;
            if( targets[middle] == key ) {
                return true;
            }
            if( targets[middle] < key ){
                left = middle+1;
            }else {
                right = middle;
            }
        }
        return false;
    }
}

