	for(int i=1;i<=N;i++) ss[i] = S.charAt(i-1);

	boolean result = true;
	for(int i=1; i<=(N-1)/4; i++){
	    int j=(N-1)/2;
	    if(ss[i]!=ss[j]){
		result = false;
	    }
	    if(ss[i + (N+3)/2]!=ss[j + (N+3)/2]){
		result = false;
	    }
	    j--;
	}
	if(result) System.out.print("Yes");
	else System.out.print("No");
    }
}

