		for (int i = 0; i < N; i++) {
			A[i] = sc.nextInt();
		}

		for (int i = 0; i < N; i++) {
			for (int j = i + 1; j < N; j++) {
				if (A[i] < A[j]) {
					int tmp = A[i];
					A[i] = A[j];
					A[j] = tmp;
				}
			}
		}

		int sum = 0;

		for(int i = 0; i < N; i++) {
			sum += A[i];
		}

		if (A[M - 1] < (sum / (4 * M))) {
			System.out.print("No");
		} else {
			System.out.print("Yes");
		}

	return;

	}
}

