	{
		 InputReader in = new InputReader(System.in);
	     OutputWriter out = new OutputWriter(System.out);
	     int a=in.readInt();
	     int b=in.readInt();
	     int t=in.readInt();
	     double d=t+0.5;
	     double q=d/a;
	     int r=(int)q;
	     out.printLine(r*b);

