		Scanner sc = new Scanner(System.in);
		int w = sc.nextInt();
		int n = sc.nextInt();
		int[] lot = new int[w];
		sc.nextLine();
		for(int i = 0 ; i < w ; i++){
			lot[i] = i+1;
		}
		for(int i = 0; i < n; i++){
			swap(lot, sc.nextLine().split(","));
