			System.out.println(lot[i]);
		}
	}
	static void swap(int[] source, String[] s){
		int a = Integer.parseInt(s[0])-1;
		int b = Integer.parseInt(s[1])-1;
		int tmp = source[a];
		source[a] = source[b];
		source[b] = tmp;
	}
}

