		for (int i = 0; i < q; i++) {
			t[i] = sc.nextInt();
		}
		sc.close();

		int count = 0;
		for(int sagasu : t) {
			if(binarySearch(s, sagasu) != -1) count++;
		}

		System.out.println(count);
	}

	private static int binarySearch(int[] ary, int target) {
		int low = 0;
		int high = ary.length-1;
		int mid = (low + high) / 2;

		while(low < high) {

			if(ary[mid] == target) return mid;

			if(ary[mid] < target) {
				low = mid + 1;
			} else {
				high = mid;
			}
			mid = (low + high) / 2;

		}
		return -1;
	}
}

