	private static long pow10E97(long ob, int soeji){
		if(soeji==2) return (ob*ob)%e97;

		int d = getDigit2(soeji);
		long[] ob_pow_2pow = new long[d];

		ob_pow_2pow[0] = ob;
		for(int i=1; i<d; i++){
			ob_pow_2pow[i] = (ob_pow_2pow[i-1]*ob_pow_2pow[i-1])%e97;
		}

		long ans=1;
		for(int i=d-1; i>=0; i--){
			if(soeji >= (1<<i)){
				soeji -= (1<<i);
				ans = (ans*ob_pow_2pow[i])%e97;
			}
 		}

		return ans;
	}

