public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";
	private static void solve() {
		int count = 0;
		while(true){
			int W = ni();
			int H = ni();
			if(W==0&&H==0) return;
			if(count!=0) System.out.println();
