			y[j] = all[(j-2)/3];
		}

		int judge = 0;

		if(x[0] + y[0] <= t[0] && (x[0]+y[0]-t[0])%2 == 0) {
			judge += 1;
		}else {
			judge += 0;
		}

		for(int k=1; k<N; k++) {
