	static int divide1000(int num){
	return num / 1000;
	}
	static int divide100(int num){
	return (num % 1000) / 100;
	}
	static int divide10(int num){
	return (num % 100) / 10;
	}
	static int divide1(int num){
	return (num % 10) / 1;
	}
}

