	static int donuts(Scanner sc){
		int n = sc.nextInt();
		int m = sc.nextInt();


		int min = 999999;
		List<Integer> l = new ArrayList<Integer>();
		for(int i = 0 ; i < n ; ++i){
			int a = sc.nextInt();
			l.add(a);
