        int wa_count = 0;
        for (int i = 0; i < m; i++) {
            int p = Integer.parseInt(sc.next()); // 提出した問題番号
            String s = sc.next(); // 結果
            // 正答済みの問題番号はスキップ
            if (ac.contains(p)) {
                continue;
            }
            // 結果がACの場合
            if (s.equals("AC")) {
                ac_count++; // 正答数を加算
                ac.add(p); // 問題番号をHashSetに格納
                continue;
            }
            // 上記以外はWAとして扱う
            wa_count++; // ペナルティ数を加算
            if (wa.containsKey(p)) {
                wa.replace(p, wa_count);
            } else {
                wa.put(p, wa_count);
            }
        }
        // 一度も正答しなかった問題番号はペナルティにならない
        for (Integer i : wa.keySet()) {
            if (!ac.contains(i)) {
                wa_count -= wa.get(i);
            }
        }
        System.out.println(String.format("%s %s", ac_count, wa_count));
        sc.close();
    }
}

