public class Main {
    public static int cStep(int[] arr){
        int steps = 0;
        for (int i = 0; i <arr.length-1; i++) {
            if(arr[i+1]<arr[i]){
                int diff = arr[i]-arr[i+1];
                // update the array next value with this
                arr[i+1] += diff;
                steps +=diff;
            }
        }
        return steps;
    }


