        ArrayList<Long> res = new ArrayList<Long>();
        for (int i = 1; i <= a.size(); i++) {
            if (i == a.size()) {
                res.add((k - a.get(a.size() - 1)) + a.get(0));
            } else {
                res.add(a.get(i) - a.get(i-1));
            }
        }
        res.sort(Comparator.reverseOrder());
        System.out.println(k-res.get(0));
    }
