        for (int i = 1; i <= n; i++) {
            h[i] = Integer.parseInt(hh[i-1]);
        }

        int[] dp = new int[n+1];
        dp[0] = 0;
        dp[1] = 0;
        for (int i = 2; i <= n; i++) {
            dp[i] += Math.min(dp[i-1] + Math.abs(h[i]-h[i-1]), dp[i-2] + Math.abs(h[i]-h[i-2]));
        }
        System.out.println(dp[n]);
    }

    public static int counter(int n) {
        if (n == 0) return 0;
        return counter(n-1) + n;
    }

}



