public class Main {

	public static void main(String[] args) {
		FastScanner fs = new FastScanner();
		String s = fs.next();
		String t = fs.next();
		int l = t.length();
		int min=l;
		int  step=0;
		for(int i=0;i<s.length();i++) // cabacc
		{                             // abc

			if(i+l>s.length())
			{
				break;
			}
