			{
				String sub = s.substring(i, i+l);
				for(int j=0;j<t.length();j++)
				{
					if(t.charAt(j)!=sub.charAt(j))
						step++;
				}
				if(step<=min)
					{
						min=step;
						step=0;
					}
			}
		}
		System.out.println(min);
	}


