        ans += ((B/C) - ((A-1)/C));        
       // System.out.println(ans);
        ans += ((B/D) - ((A-1)/D));
       // System.out.println(ans);
        ans -= ((B/g) - ((A-1)/g));

        System.out.println((B-A+1) - ans);

    }
    static long gcd (long a, long b){
        long temp;
        while((temp = a%b) != 0){
            a = b;
            b = temp;
        }
        return b;
    }
}

