    private static void insertionSort(int[] ary, int n) {
        showArray(ary);
        for(int i = 1; i < n; i++) {
            int v = ary[i];
            int j = i - 1;
            while(j >= 0 && ary[j] > v) {
                ary[j + 1] = ary[j];
                j--;
            }
            ary[j + 1] = v;
            showArray(ary);
        }
    }
}

