	static class Task {
		public void solve(int testNumber, InputReader in, PrintWriter out) {
			int l = in.nextInt();
			int r = in.nextInt();
			if (l - r > 2020) {
				r = l + 2020;
			}
			long ans = Long.MAX_VALUE;
			for (int i = l; i <= r; i++) {
				for (int j = l + 1; j <= r; j++) {
					ans = Math.min(ans, (i * j) % 2019);
				}
			}
			out.println(ans);
		}
	}

