            int d = n % (a + b);
            if (d - a > 0) {
                System.out.println((c * a) + a);
            } else {
                System.out.println((c * a) + d);
            }
        } else {
            // 数える数がボール投入数より少ない場合
            if (n - a >= 0) {
                System.out.println(a);
            } else {
                System.out.println(n);
            }

        }
        sc.close();
    }
}

