		FastScannerWelcomeToAtCoder sc = new FastScannerWelcomeToAtCoder(System.in);

		try {
			int N = sc.nextInt();
			int M = sc.nextInt();
			int[] p = new int[M];
			String[] S = new String[M];
			ArrayList<Integer> ac = new ArrayList<Integer>();

			for (int m = 0; m < M; m++) {
				p[m] = sc.nextInt();
				S[m] = sc.nextLine().trim();
			}

			int ans_c = 0;
			int ans_p = 0;

			/*
			 * 1 M:同じ問題複数
			 * 2 M:なし → そもそもwhileに入らない
			 * 3 M:問題が飛ぶ → iを進めたらだめ
			 */

			for (int m = 0; m < M; m++) {
				if (ac.contains(p[m])) {
					continue;
				}

				if (S[m].equals("AC")) {
					ans_c++;
					ac.add(p[m]);
				} else {
					ans_p++;
				}
			}

			System.out.println(ans_c + " " + ans_p);
