    private static void solve(int q, FastScanner in, PrintWriter out) {
        for(int qq = 0; qq < q; qq++) {
            int n = in.nextInt();
            int[] h = new int[n];
            for(int i = 0; i < n; i++) {
                h[i] = in.nextInt();
            }
            int[] dp = new int[n];
            dp[0] = 0;
            dp[1] = Math.abs(h[1] - h[0]);
            for(int i = 2; i < n; i++) {
                dp[i] = Math.min(dp[i - 1] + Math.abs(h[i] - h[i - 1]), dp[i - 2] + Math.abs(h[i] - h[i - 2]));
            }
            out.println(dp[n - 1]);
        }
        out.close();
    }

