class Main{
  public static void main(String args[]){
    Scanner sc = new Scanner(System.in);
    final int modder=1000000007;
    int n=sc.nextInt();
    int m=sc.nextInt();
    int dp[]=new int[n+1];
    Arrays.fill(dp,0);
    for(int i=0;i<m;i++){
      dp[sc.nextInt()]=-1;
    }
