            } else if (num < 2800) {
                bit |= 64;
            } else if (num < 3200) {
                bit |= 128;
            } else {
                over++;
            }
        }

        if (c > 8) c = 8;
        int count = Integer.bitCount(bit);
        int max = count + over;

        if (count == 0) count = 1;
        if (max > c) max = c;

        System.out.print(count + " " + max);
    }
}

