        sc.close();
    }

    static int solve(String S) {
        int result = 0;
        int count = 0;
        for (char ch : S.toCharArray()) {
            if ("ATCG".indexOf(ch) >= 0) {
                ++count;
                result = Math.max(result, count);
            } else {
                count = 0;
            }
        }

        return result;
    }
}

import java.util.Scanner;

class Main {
	static int quantum = 0;
	public static void main (String [] args) {
		Scanner scan = new Scanner (System.in);

		//プロセス数
		int n = scan.nextInt();
		String[] str = new String[n];
		int[] data = new int[n];

		//クオンタム
		int q = scan.nextInt();

		for (int i = 0; i < n; i++) {
			str[i] = scan.next();
			data[i] = scan.nextInt();
		}
		scan.close();

		MainTest obj = new MainTest();
		obj.Queue(str, data, q);
	}

	void Queue (String[] str, int[] data, int q) {
		int count = 0;
		int head = 0;
		int top = data.length;

		while (true) {
			if ( data[head] != 0) {
				data[head] = Quantum(data[head], q);
				if (data[head] == 0) {
					count++;
					System.out.println(str[head] + " " + quantum);
				} 
			}

			if (count == top) break;

			head++;
			if (head == top) head = 0;
		}
	}

	int Quantum(int x, int q) {

		if ( x < q) {
			quantum += x;
			return 0;
		} else {
			x -= q;
			quantum += q;
		}

		return x;

	}
}

