public class Main {
	public static void main(String[] args) {
		Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
		int n = in.nextInt();
		int d = in.nextInt();
		int[][] x = new int[n][d];
		for (int i = 0; i < n; i++)
			for (int j = 0; j < d; j++)
				x[i][j] = in.nextInt();
		System.out.println(solve(x));
		in.close();
	}

	private static int solve(int[][] x) {
		int r = 0;
		for (int i = 0; i < x.length; i++)
			for (int j = i + 1; j < x.length; j++)
				if (isOk(x[i], x[j]))
					r++;
		return r;
	}

	private static boolean isOk(int[] a, int[] b) {
		long r = 0;
		for (int i = 0; i < a.length; i++)
			r += Math.pow(a[i] - b[i], 2);
		long r2 = (long) Math.pow(r, 0.5);
		if (r2 * r2 == r)
			return true;
		else
			return false;
	}
}

import java.util.LinkedList;
import java.util.Scanner;
import java.util.Queue;

class Main {

    static class Process{
        String name;
        int time;

        Process(String n, int t){
            name = n;
            time = t;
        }
        void updateTime(int t){
            time -= t;
        }
    }


    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int quantum = sc.nextInt();

        Queue<Process> queue = new LinkedList<>();

        for (int i = 0; i < n; i++)
            queue.add(new Process(sc.next(), sc.nextInt()));

        int elapsed = 0;
        while (queue.size() > 0){
            Process p = queue.poll();
            if (p.time <= quantum){
                elapsed += p.time;
                System.out.println(p.name + " " + elapsed);
            }
            else{
                elapsed += quantum;
                p.updateTime(quantum);
                queue.offer(p);
            }
        }
    }
}

