public static void main(String[]args) {
	Scanner sc= new Scanner(System.in);
	int a=sc.nextInt();
	int b=sc.nextInt();
	int h=sc.nextInt();
	int m=sc.nextInt();
	int hr=h*30+m/2;
	int min=m/5 * 30 + m%5 * 30/5;
